/*
 * Combines the scripts referenced by runner.js into one parser-blocking file.
 * Run from the runtime root: node scripts/build-runtime-bundle.js
 */
const fs = require("fs");
const path = require("path");
const { minify } = require("terser");

const runtimeRoot = path.resolve(__dirname, "..");
const runnerPath = path.join(__dirname, "runner.js");
const bundleBanner = "/* GameMaker HTML5 Runtime bundle. Generated by scripts/build-runtime-bundle.js. */";
const retainedComment = /@(?:if|else|endif|license|preserve)\b|NO_OBFUSCATE|copyright|permission is hereby granted|\bSPDX\b|^!/i;
const manifestPath = path.join(__dirname, "runtime.bundle.manifest.json");
const scriptPaths = JSON.parse(fs.readFileSync(manifestPath, "utf8"));

if (scriptPaths.length === 0) {
    throw new Error("The runtime bundle manifest is empty.");
}

const bundle = [
    bundleBanner,
    "/* Source order is preserved because the runtime uses global scripts. */",
    ""
];

for (const scriptPath of scriptPaths) {
    const sourcePath = path.join(runtimeRoot, scriptPath);
    if (!fs.existsSync(sourcePath)) {
        throw new Error(`Referenced runtime source does not exist: ${scriptPath}`);
    }

    bundle.push(`\n/* ===== BEGIN ${scriptPath} ===== */\n`);
    bundle.push(fs.readFileSync(sourcePath, "utf8"));
    bundle.push(`\n/* ===== END ${scriptPath} ===== */\n`);
}

async function build() {
    const readable = process.argv.includes("--readable");
    const source = bundle.join("");
    // GML, extensions, and the scheduler call runtime globals by name.
    // Keep compiler directives and license notices in the generated bundle.
    const output = readable ? source : (await minify(source, {
        compress: false,
        mangle: false,
        format: {
            max_line_len: 2000,
            preamble: bundleBanner,
            comments: (_node, comment) => {
                if (!retainedComment.test(comment.value)) return false;
                comment.value = comment.value.trimEnd();
                return true;
            },
        },
    })).code + "\n";

    fs.writeFileSync(path.join(__dirname, "runtime.bundle.js"), output, "utf8");
    fs.writeFileSync(runnerPath, [
        "// GameMaker HTML5 Runtime bootstrap.",
        `// The original ${scriptPaths.length} synchronous script requests are combined into one file.`,
        "// Source order is preserved in scripts/runtime.bundle.js.",
        "document.write('<script type=\"text/javascript\" src=\"scripts/runtime.bundle.js\"></script>');",
        "// Keep the ACTUAL-RUNTIME RAF scheduler patch after the runtime bundle.",
        "document.write('<script type=\"text/javascript\" src=\"scripts/runtime.frame-scheduler-patch.js\"></script>');",
        ""
    ].join("\n"), "utf8");

    console.log(`Built ${readable ? "readable" : "compact"} runtime.bundle.js from ${scriptPaths.length} runtime scripts.`);
}

build().catch(error => {
    console.error(error);
    process.exitCode = 1;
});
